from mk import *
from lib import fbd
STRICT["on"] = True
import math

def fig():
    g = Fig(560, 390, "מסילה במישור אנכי: הגוף m משוחרר מהנקודה A בגובה H = 3 מטר מעל המישור MN, יורד ל-B בתחתית, עולה ל-C בגובה h = 1 מטר, ונע בקטע אופקי מחוספס CD. בקצה הקטע קפיץ רפוי מחובר לקיר, והגוף נעצר בנקודה F")
    g.ground(40, 520, 230)
    g.path("M 100,60 Q 150,50 200,170 Q 230,240 260,200 Q 280,170 300,170 L 410,170 L 500,170", width=2.5)
    g.block(108, 52, 18, 12, None, fill="var(--d-fill)"); g.text(96, 54, "A", anchor="end")
    g.dim(70, 60, 70, 230, "H", offset=0); g.dim(310, 170, 310, 230, "h", offset=0)
    g.spring(420, 160, 480, 160, coils=7, amp=8); g.rect(480, 120, 10, 50, fill="var(--d-label)", stroke="none", width=0)
    for x, y, t in ((52, 246, "M"), (232, 246, "B"), (300, 158, "C"), (420, 186, "D"), (446, 186, "F"), (510, 246, "N")): g.text(x, y, t)
    for x in range(310, 410, 14): g.line(x, 174, x + 8, 182, stroke="var(--d-dim)", width=1)
    # the table from part א (energies at each point; A filled in as the example)
    x0, y0, hw, cw, rh = 40, 266, 150, 60, 26
    cols = ["A", "B", "C", "D", "F"]; rows = [("קינטית", "0"), ("פוטנציאלית כובדית", "+"), ("פוטנציאלית אלסטית", "0")]
    W_ = hw + cw * len(cols)
    g.rect(x0, y0, W_, rh * 4, fill="none", width=1.2)
    for r in range(1, 4): g.line(x0, y0 + rh * r, x0 + W_, y0 + rh * r, width=0.8)
    for c in range(len(cols)): g.line(x0 + W_ - hw - cw * c, y0, x0 + W_ - hw - cw * c, y0 + rh * 4, width=0.8)
    g.heb(x0 + W_ - hw / 2, y0 + 18, "האנרגיה \\ הנקודה")
    for c, lab in enumerate(cols): g.text(x0 + W_ - hw - cw * (c + 0.5), y0 + 18, lab)
    for r, (name, a) in enumerate(rows):
        g.heb(x0 + W_ - hw / 2, y0 + rh * (r + 1) + 18, name); g.text(x0 + W_ - hw - cw * 0.5, y0 + rh * (r + 1) + 18, a)
    return g

vC = math.sqrt(40); vD = math.sqrt(34); k = 1.5 * 34 / 0.01
E(id="bagrut-2010-q4", year=2010, label="2010 שאלה 4", topic="energy", sub="en-friction", diff=4, fig=fig,
  stem=r"התרשים מראה מסילה במישור אנכי, ועליה נע גוף קטן שמסתו $m$. הקטע $ABC$ חלק, והקטע האופקי $CD$ מחוספס, עם מקדם חיכוך קינטי $\mu_k$. בקצה הקטע $CD$ יש קפיץ רפוי שמחובר לקיר, והמשטח שמתחת לקפיץ חלק. משחררים את הגוף ממנוחה בנקודה $A$, בגובה $H$ מעל מישור הייחוס $MN$. הגוף נע על המסילה עד הנקודה $F$, ושם הוא נעצר לרגע אחרי שכיווץ את הקפיץ. נתון: $CD = 1\,\text{m}$, $DF = 0.1\,\text{m}$, $m = 1.5\,\text{kg}$, $H = 3\,\text{m}$, $h = 1\,\text{m}$, $\mu_k = 0.3$.",
  parts=[
    P("א", r"הטבלה מראה את סוגי האנרגיה של הגוף בכל אחת מהנקודות $A$, $B$, $C$, $D$, $F$. העתיקו את הטבלה, וכתבו בכל משבצת \"+\" אם האנרגיה הזו לא אפס, ו-\"0\" אם היא אפס.", OPEN, ["understanding"], [
        S(r"האנרגיה הקינטית", r"היא אפס רק בנקודות שבהן הגוף עומד: בהתחלה ובכיווץ המרבי", r"E_k = 0 \;\Leftrightarrow\; v = 0", eq=r"E_k = \tfrac{1}{2}mv^2"),
        S(r"אנרגיית הגובה", r"מודדים אותה ממישור הייחוס. היא אפס רק בנקודה הנמוכה, שנמצאת על המישור", r"U_G = 0 \;\Leftrightarrow\; h = 0", eq=r"U_G = mgh"),
        S(r"האנרגיה האלסטית", r"היא לא אפס רק כשהקפיץ מכווץ", r"U_{sp} = 0 \;\Leftrightarrow\; \Delta\ell = 0", eq=r"U_{sp} = \tfrac{1}{2}K(\Delta\ell)^2"),
        TBL(r"הטבלה המלאה", ["האנרגיה", "A", "B", "C", "D", "F"], [["קינטית", "0", "+", "+", "+", "0"], ["כובדית", "+", "0", "+", "+", "+"], ["אלסטית", "0", "0", "0", "0", "+"]]),
    ], r"ראו את הטבלה המלאה בפתרון", key=r"טבלה"),
    P("ב1", r"מה המהירות של הגוף בנקודה $C$, בדרכו אל $F$?", num(vC, "m/s"), ["principle"], [
        S(r"שימור אנרגיה", r"הקטע הראשון חלק, והכוח הנורמלי לא עושה עבודה. הגוף יורד מגובה שלושה מטרים לגובה מטר אחד. המסה מצטמצמת", r"m \cdot 10 \cdot 3 = \tfrac{1}{2}m\,v_C^2 + m \cdot 10 \cdot 1 \;\Rightarrow\; v_C = \sqrt{40} \approx 6.32\,\text{m/s}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
    ], r"$\approx 6.32\,\text{m/s}$", key=r"vC≈6.32 m/s"),
    P("ב2", r"מה המהירות של הגוף בנקודה $D$, בדרכו אל $F$?", num(vD, "m/s"), ["principle"], [
        D(r"תרשים הכוחות על הגוף בקטע המחוספס", lambda: fbd([("fₖ", 180, 0.35), ("N", 90, 1.0), ("mg", -90, 1.0)],
            "תרשים כוחות על הגוף בקטע המחוספס: חיכוך קינטי נגד התנועה, הכוח הנורמלי כלפי מעלה וכוח הכובד כלפי מטה. הכיוון החיובי הוא כיוון התנועה",
            positive=0, body="block", surface="below")),
        S(r"מציבים את החיכוך", r"הקטע אופקי, ולכן הכוח הנורמלי שווה לכובד", r"f_k = \mu N = 0.3 \cdot 1.5 \cdot 10 = 4.5\,\text{N}", eq=r"f_k = \mu_k N"),
        S(r"העבודה של החיכוך", r"החיכוך נגד התנועה לאורך כל הקטע", r"W_f = f_k\cos 180^\circ \cdot 1 = -4.5\,\text{J}", eq=r"W = F\cos\theta\,\Delta s"),
        S(r"משפט העבודה והאנרגיה", r"בקטע הזה רק החיכוך עושה עבודה", r"-4.5 = \tfrac{1}{2} \cdot 1.5\,v_D^2 - \tfrac{1}{2} \cdot 1.5 \cdot 40 \;\Rightarrow\; v_D^2 = 34 \;\Rightarrow\; v_D \approx 5.83\,\text{m/s}", eq=r"W_{\text{tot}} = \Delta E_k"),
    ], r"$\approx 5.83\,\text{m/s}$", key=r"vD≈5.83 m/s"),
    P("ג", r"מה קבוע הקפיץ?", num(k, "N/m"), ["principle"], [
        S(r"שימור אנרגיה מהנקודה D לנקודה F", r"המשטח שמתחת לקפיץ חלק. כל האנרגיה הקינטית נאגרת בקפיץ, שמתכווץ עשרה סנטימטרים", r"\tfrac{1}{2} \cdot 1.5 \cdot 34 = \tfrac{1}{2}K \cdot 0.1^2", eq=r"U_{sp} = \tfrac{1}{2}K(\Delta\ell)^2"),
        S(r"פותרים", r"מבודדים את קבוע הקפיץ", r"K = \frac{25.5 \cdot 2}{0.01} = 5100\,\text{N/m}"),
    ], r"$5100\,\text{N/m}$", key=r"k=5100 N/m"),
    P("ד", r"אחרי שהגוף נעצר ב-$F$, הוא מתחיל לנוע לכיוון ההפוך ועוזב את הקפיץ. לאיזה גובה הוא עולה אחרי שעזב את הקפיץ?", num(2.4, "m"), ["principle"], [
        S(r"האנרגיה בנקודה D בחזרה", r"הקפיץ מחזיר את כל האנרגיה שנאגרה בו", r"E_k = \tfrac{1}{2} \cdot 1.5 \cdot 34 = 25.5\,\text{J}"),
        S(r"אחרי הקטע המחוספס", r"החיכוך שוב לוקח את אותה אנרגיה", r"25.5 - 4.5 = 21\,\text{J}", eq=r"W_{\text{nc}} = \Delta E"),
        S(r"הגובה", r"הקטע העקום חלק. מגובה הקטע המחוספס הגוף עולה עוד, עד שכל האנרגיה הקינטית הופכת לאנרגיית גובה", r"21 = 1.5 \cdot 10 \cdot \Delta h \;\Rightarrow\; \Delta h = 1.4\,\text{m},\qquad 1 + 1.4 = 2.4\,\text{m}", eq=r"U_G = mgh"),
    ], r"$2.4\,\text{m}$ מעל $MN$", key=r"2.4 m"),
    P("ה", r"מחליפים את הקפיץ בקפיץ באותו אורך, עם קבוע גדול יותר, ושוב משחררים את הגוף ממנוחה ב-$A$. האם הגובה שאליו יעלה הגוף אחרי שיעזוב את הקפיץ יהיה קטן מהגובה בסעיף ד, גדול ממנו או שווה לו? הסבירו.", choice(["קטן", "גדול", "שווה"], 2), ["principle"], [
        S(r"הקפיץ לא מאבד אנרגיה", r"הקפיץ הקשה יותר מתכווץ פחות, אבל הוא אוגר ומחזיר את אותה אנרגיה. החיכוך בקטע המחוספס לא השתנה", r"U_{sp} = \tfrac{1}{2}m\,v_D^2"),
    ], r"שווה", key=r"שווה לו"),
  ],
  concepts=["סוגי אנרגיה", "שימור אנרגיה", "עבודת חיכוך", "אנרגיה אלסטית"],
  summary=r"גוף שגולש, עובר קטע מחוספס, מכווץ קפיץ וחוזר: המהירויות, קבוע הקפיץ, והגובה שאליו הוא חוזר.",
  review="הנחה שלי.\nבסעיף א יש בפתרון את הטבלה המלאה.\nמה לבדוק: רק לאשר.")
